SELECT campaign_country, behavior_segment_id, MAX(behavior_segment_name) AS segment_name, MAX(behavior_segment_description) AS segment_description, BUILT_IN_PARAMETER('TIME_WINDOW_START') AS time_window_start, BUILT_IN_PARAMETER('TIME_WINDOW_END') AS time_window_end FROM dsp_impressions_by_matched_segments WHERE campaign_country = CUSTOM_PARAMETER('dsp_campaign_country') GROUP BY campaign_country, behavior_segment_id
